{"query": "
-- ============================================================
-- TASK 3: Create Constraint Enforcement System
-- ============================================================

-- ── Drop any pre-existing artifacts to ensure idempotency ───────────────────
DROP TRIGGER IF EXISTS trg_check_parts_lego_sets            ON public.lego_sets;
DROP TRIGGER IF EXISTS trg_check_parts_lego_inventories     ON public.lego_inventories;
DROP TRIGGER IF EXISTS trg_check_parts_lego_inventory_parts ON public.lego_inventory_parts;
DROP FUNCTION IF EXISTS public.check_set_parts_consistency();

-- ============================================================
-- Part A: Create the Trigger Function
-- ============================================================
CREATE OR REPLACE FUNCTION public.check_set_parts_consistency()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    v_set_num          TEXT;
    v_actual_parts     INTEGER;
    v_stored_num_parts INTEGER;
BEGIN
    -- ── 1. Determine which set_num we need to validate ───────────────────────
    --
    --  • lego_sets            → set_num is a direct column on the affected row
    --  • lego_inventories     → set_num is a direct column on the affected row
    --  • lego_inventory_parts → must look up the parent inventory to find set_num

    IF TG_TABLE_NAME = 'lego_sets' OR TG_TABLE_NAME = 'lego_inventories' THEN
        v_set_num := NEW.set_num;

    ELSIF TG_TABLE_NAME = 'lego_inventory_parts' THEN
        SELECT set_num
          INTO v_set_num
          FROM public.lego_inventories
         WHERE id = NEW.inventory_id;

        -- If the parent inventory row doesn't exist yet, skip the check.
        IF NOT FOUND THEN
            RETURN NEW;
        END IF;

    ELSE
        -- Unknown table – skip safely
        RETURN NEW;
    END IF;

    -- ── 2. Retrieve the stored num_parts for this set ────────────────────────
    SELECT num_parts
      INTO v_stored_num_parts
      FROM public.lego_sets
     WHERE set_num = v_set_num;

    -- If the set itself doesn't exist yet (e.g., during a bulk load), skip.
    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    -- ── 3. Calculate the actual non-spare part count from the latest inventory ─
    SELECT COALESCE(SUM(lip.quantity), 0)
      INTO v_actual_parts
      FROM public.lego_inventories AS li
      -- Only the latest version for this set
      INNER JOIN (
          SELECT set_num, MAX(version) AS max_version
            FROM public.lego_inventories
           WHERE set_num = v_set_num
           GROUP BY set_num
      ) AS latest
          ON li.set_num  = latest.set_num
         AND li.version  = latest.max_version
      -- Only non-spare parts
      INNER JOIN public.lego_inventory_parts AS lip
          ON lip.inventory_id = li.id
         AND lip.is_spare     = false
      WHERE li.set_num = v_set_num;

    -- ── 4. Skip the check if the set has no inventory records at all ──────────
    --   (v_actual_parts = 0 could mean "no inventory" OR "legitimately 0 parts")
    --   We disambiguate by checking whether any inventory row exists.
    IF v_actual_parts = 0 THEN
        PERFORM 1
          FROM public.lego_inventories
         WHERE set_num = v_set_num
         LIMIT 1;

        -- No inventory at all → skip check as specified in the requirements
        IF NOT FOUND THEN
            RETURN NEW;
        END IF;
    END IF;

    -- ── 5. Enforce the invariant ──────────────────────────────────────────────
    IF v_actual_parts IS DISTINCT FROM v_stored_num_parts THEN
        RAISE EXCEPTION
            'Inconsistent part count for set %: stored num_parts=% but actual non-spare parts=%',
            v_set_num,
            v_stored_num_parts,
            v_actual_parts;
    END IF;

    RETURN NEW;
END;
$$;
"}

{"query": "
-- ── V3: Live trigger enforcement test – should BLOCK a bad UPDATE ─────────────
-- Pick a real set and deliberately make num_parts wrong; expect an exception.
DO $$
DECLARE
    v_set   TEXT := '3806-1';
    v_saved INTEGER;
BEGIN
    -- Remember the current (correct) value
    SELECT num_parts INTO v_saved FROM public.lego_sets WHERE set_num = v_set;

    -- Attempt to write an obviously wrong value
    BEGIN
        UPDATE public.lego_sets SET num_parts = 9999 WHERE set_num = v_set;
        -- If we reach here the trigger failed to fire
        RAISE NOTICE 'BAD: trigger did NOT block the inconsistent update!';
        -- Roll back the corruption
        UPDATE public.lego_sets SET num_parts = v_saved WHERE set_num = v_set;
    EXCEPTION
        WHEN OTHERS THEN
            RAISE NOTICE 'GOOD: trigger correctly blocked the update. Error: %', SQLERRM;
    END;
END;
$$;
"}

{"query": "
-- ── V3b: Capture the NOTICE messages from the trigger enforcement test ────────
DO $$
DECLARE
    v_set    TEXT    := '3806-1';
    v_saved  INTEGER;
    blocked  BOOLEAN := FALSE;
BEGIN
    SELECT num_parts INTO v_saved FROM public.lego_sets WHERE set_num = v_set;

    BEGIN
        UPDATE public.lego_sets SET num_parts = 9999 WHERE set_num = v_set;
    EXCEPTION
        WHEN OTHERS THEN
            blocked := TRUE;
            RAISE NOTICE 'Trigger BLOCKED bad update for %  |  Error: %', v_set, SQLERRM;
    END;

    IF NOT blocked THEN
        -- Must not happen; roll back corruption
        UPDATE public.lego_sets SET num_parts = v_saved WHERE set_num = v_set;
        RAISE EXCEPTION 'Trigger did NOT fire – system is broken!';
    END IF;
END;
$$;
"}

